        emailBody.setBody("<H1>Hi Christian</H1><p>Hope you are good</p>");
        emailBody.setSubject("test");

        EmailAddress emailAddress1 = new EmailAddress();
        emailAddress1.setDisplayName("Test");
        emailAddress1.setEmail("info@lqwd.money");
        emailAddress1.setRecipientType(RecipientType.TO);

        EmailAddress emailAddress2 = new EmailAddress();
        emailAddress2.setDisplayName("Test");
        emailAddress2.setEmail("christian@lqwd.money");
        emailAddress2.setRecipientType(RecipientType.TO);

        EmailAddress emailAddress3 = new EmailAddress();
        emailAddress3.setDisplayName("Chris");
        emailAddress3.setEmail("okemedjbabs@gmail.com");
        emailAddress3.setRecipientType(RecipientType.CC);

        EmailAddress emailAddress4 = new EmailAddress();
        emailAddress4.setDisplayName("Baba");
        emailAddress4.setEmail("dopestweet@gmail.com");
        emailAddress4.setRecipientType(RecipientType.BCC);

        emailBody.setRecipients(Arrays.asList(emailAddress2,emailAddress3,emailAddress4));
